import solution


def test_issue_example_10_15():
    """Example: sum(10,15) == 6."""
    assert solution.sum(10, 15) == 6  # 1+5=6


def test_issue_identical_inputs_12_12():
    """Common divisors of equal inputs are all divisors so sum(12,12) is 28."""
    assert solution.sum(12, 12) == 28  # 1+2+3+4+6+12=28


def test_issue_coprime_8_9():
    """Coprime inputs share only 1 so sum(8,9) is 1."""
    assert solution.sum(8, 9) == 1  # 1=1


def test_issue_one_divides_other_6_12():
    """If one input divides the other sum(6,12) is 12."""
    assert solution.sum(6, 12) == 12  # 1+2+3+6=12


def test_issue_one_and_other_1_7():
    """Common divisors with 1 are only 1 so sum(1,7) is 1."""
    assert solution.sum(1, 7) == 1  # 1=1


def test_issue_both_one():
    """Common divisors of 1 and 1 are only 1 so sum(1,1) is 1."""
    assert solution.sum(1, 1) == 1  # 1=1


def test_issue_distinct_primes_13_17():
    """Distinct primes share only 1 so sum(13,17) is 1."""
    assert solution.sum(13, 17) == 1  # 1=1


def test_issue_swapped_arguments_15_10():
    """Order does not matter so sum(15,10) is still 6."""
    assert solution.sum(15, 10) == 6  # 1+5=6


def test_issue_larger_pair_100_150():
    """Sum of common divisors of 100 and 150 is 93."""
    assert solution.sum(100, 150) == 93  # 1+2+5+10+25+50=93


def test_issue_small_pair_2_4():
    """Sum of common divisors of 2 and 4 is 3."""
    assert solution.sum(2, 4) == 3  # 1+2=3


def test_contract_sum_is_callable():
    """Public interface requires solution.sum(a, b) to be callable."""
    assert callable(solution.sum)


def test_contract_returns_int():
    """Public interface example returns integer 6 so result is int."""
    assert isinstance(solution.sum(10, 15), int)
